// Üretilen dosya: tool/ozgun/uret.py. Tarih · Denizcilik tarihi, boğazlar, kanallar, ünlü denizciler ve deniz muharebeleri (Fenikeliler, Piri Reis, Barbaros, Preveze, İnebahtı, Trafalgar, Süveyş, Panama) (kolay).
const ozHistory16Kolay = <(String, String, List<String>, String)>[
  ('MÖ 12. yüzyıldan itibaren Lübnan sedirlerini kullanarak Akdeniz genelinde ticaret kolonileri kuran ve alfabenin deniz yoluyla yayılmasına öncülük eden uygarlık hangisidir?', 'Fenikeliler', ['Asurlular', 'Hititler', 'Frigyalılar'], 'Fenikeliler Sur, Sayda ve Biblos gibi kıyı kentlerinden hareketle Akdeniz\'de geniş bir deniz ticaret ağı ve koloniler kurmuştur.'),
  ('Antik Yunan donanmalarında her iki yanında üst üste üç sıra kürekçi dizilimi bulunan ve pruvasındaki tunç mahmuzla düşman gemilerini delerek batıran savaş gemisi tipine ne ad verilir?', 'Trireme', ['Karavela', 'Kalyon', 'Galeas'], 'Trireme (üç sıra kürekli gemi), Klasik Çağ Akdeniz deniz muharebelerinin en hızlı ve manevra kabiliyeti yüksek savaş gemisiydi.'),
  ('MÖ 31 yılında Octavianus ile Marcus Antonius-Kleopatra ittifakı arasında Yunanistan\'ın batı kıyılarında gerçekleşen ve Roma\'da İmparatorluk Dönemi\'nin kapısını açan deniz savaşı hangisidir?', 'Aktium Deniz Muharebesi', ['Salamis Deniz Muharebesi', 'Egos Potamoi Muharebesi', 'Mylae Deniz Muharebesi'], 'Agrippa komutasındaki Octavianus donanması Aktium\'da galip gelerek Roma\'nın Akdeniz üzerindeki tek hâkimiyetini kesinleştirmiştir.'),
  ('Doğu Roma (Bizans) donanmasının Arap kuşatmalarına karşı Konstantinopolis\'i savunurken sifonlarla püskürttüğü ve suyla temas ettiğinde sönmeyen gizli silahın tarihsel adı nedir?', 'Rum ateşi', ['barutlu humbara', 'neft okları', 'tuzlu güherçile'], 'Kallinikos tarafından geliştirilen Rum ateşi (Grejuva), Bizans dromonlarının deniz savaşlarında yüzyıllarca üstünlük kurmasını sağlamıştır.'),
  ('İskandinav denizcilerinin hem açık okyanus dalgalarına dayanacak esneklikte hem de sığ nehirlere girebilecek kadar az su çekimli inşa ettikleri bindirme kaplamalı gemilere ne ad verilir?', 'Drakkar', ['Dromon', 'Kadırga', 'Baştarda'], 'Pruvasındaki ejderha başı oymalarından ötürü Drakkar denilen Viking uzun gemileri, bindirme ahşap (clinker) tekniğiyle üretilmiştir.'),
  ('MS 1000 yılı civarında Grönland\'dan batıya yelken açarak Kuzey Amerika\'nın Newfoundland kıyılarına ulaşan ve burayı \'Vinland\' olarak adlandıran İzlandalı denizci kimdir?', 'Leif Erikson', ['Kızıl Erik', 'Rollo', 'Harald Hardrada'], 'Kızıl Erik\'in oğlu Leif Erikson, Kolomb\'dan yaklaşık beş yüzyıl önce Kuzey Amerika ana karasına ayak basan Avrupalı denizcidir.'),
  ('Büyük Okyanus\'taki binlerce adayı pusula veya metal alet kullanmadan yıldızların doğuş noktaları, okyanus dalga kırılmaları ve kuşların uçuş yönleriyle kolonileştiren topluluk hangisidir?', 'Polinezyalılar', ['İnkalar', 'Aztekler', 'Aborjinler'], 'Polinezyalılar çift gövdeli kanoları ve dalga çubuğu haritalarıyla Hawaii, Paskalya Adası ve Yeni Zelanda\'dan oluşan büyük üçgene yayılmıştır.'),
  ('1274 ve 1281 yıllarında Kubilay Han\'ın Japonya\'yı istila etmek için gönderdiği devasa Moğol-Kore-Çin donanmalarını batırarak Japoncada \'Kutsal Rüzgâr\' olarak adlandırılan doğa olayı nedir?', 'Kamikaze tayfunları', ['Kuroşivo akıntısı', 'Pasifik tsunamisi', 'El Nino fırtınası'], 'Hakata Körfezi\'ndeki istila filolarını iki kez yok eden şiddetli tayfunlar Japonlar tarafından \'Kamikaze\' (ilahi rüzgâr) olarak adlandırılmıştır.'),
  ('Orta Çağ\'da Akdeniz denizciliğinde kare yelkenin yerini alarak gemilerin rüzgârı yalnızca arkadan değil yandan ve çaprazdan da alarak ilerlemesine imkân tanıyan üçgen yelken türü nedir?', 'Latin yelken', ['Babayafingo yelken', 'Gabyer yelken', 'Civadra yelken'], 'Üçgen biçimli Latin yelken, rüzgâra dar açıyla (orsa seyrinde) manevra kabiliyeti sağlayarak açık deniz keşiflerinin de önünü açmıştır.'),
  ('Ceneviz Cumhuriyeti\'nin 13. yüzyılda Bizans ile imzaladığı Nymphaion (Kemalpaşa) Antlaşması sonucunda İstanbul\'da elde ettiği ve Karadeniz ticaretini yönettiği özerk koloni merkezi neresidir?', 'Galata', ['Kadıköy', 'Bakırköy', 'Üsküdar'], '1261 Nymphaion Antlaşması ile Venedik\'e karşı Ceneviz desteğini alan VIII. Mihail Palaiologos, Cenevizlilere Galata\'da geniş imtiyazlar tanımıştır.'),
  ('MÖ 477 yılında Pers tehdidine karşı Atina öncülüğünde Ege adaları ve kıyı kentlerinin gemi ya da para katkısıyla kurdukları deniz ittifakı hangisidir?', 'Attika-Delos Deniz Birliği', ['Peloponez Birliği', 'Korint İttifakı', 'İyonya On İki Kent Birliği'], 'Hazinesi başlangıçta kutsal Delos Adası\'nda tutulan birlik, zamanla Atina\'nın kendi deniz imparatorluğuna dönüşmüştür.'),
  ('MÖ 214-212 yıllarındaki Siraküza Kuşatması sırasında Roma donanmasının gemilerini dev pençe vinçler ve mancınıklarla etkisiz hale getiren savunma düzeneklerini hangi bilgin tasarlamıştır?', 'Arşimet', ['Öklid', 'Pisagor', 'Batlamyus'], 'Suyun kaldırma kuvvetini de keşfeden Siraküzalı Arşimet, \'Arşimet Pençesi\' adı verilen kaldıraçlı kancalarla kıyıya yanaşan Roma gemilerini alabora etmiştir.'),
  ('Antik Mısır\'da Keops Piramidi\'nin yanındaki kapalı taş çukurda parçalar halinde gömülü bulunan ve sedir ağacından çivisiz halat bağlantılarıyla yapılmış 43 metrelik gemi ne amaçla inşa edilmiştir?', 'Firavunun öteki dünya yolculuğu için güneş teknesi', ['Akdeniz korsanlarına karşı devriye kadırgası', 'İskenderiye Limanı için yük mavnası', 'Roma tahıl sevkiyatı için açık deniz gemisi'], 'MÖ 2500 civarına tarihlenen Khufu (Keops) Güneş Teknesi, antik gemicilik mimarisinin günümüze eksiksiz ulaşan en eski anıtsal örneğidir.'),
  ('Antalya\'nın Kaş ilçesi açıklarında keşfedilen ve MÖ 14. yüzyıla ait bakır külçeler, kalay, kobalt mavisi cam ve Kraliçe Nefertiti\'nin altın mührünü taşıyan Tunç Çağı gemi batığı hangisidir?', 'Uluburun Batığı', ['Yenikapı Batığı', 'Serçe Limanı Batığı', 'Vasa Batığı'], 'Uluburun Batığı, Geç Tunç Çağı\'nda Doğu Akdeniz uygarlıkları arasındaki uluslararası deniz ticaretinin zenginliğini kanıtlayan eşsiz bir sualtı buluntusudur.'),
  ('İstanbul\'da Marmaray kazıları sırasında gün yüzüne çıkarılan, 37 adet Bizans dönemi ticaret ve kürekli savaş gemisi kalıntısına ev sahipliği yapan antik liman hangisidir?', 'Theodosius Limanı', ['Altınboynuz Tersanesi', 'Kadırga Bukoleon Limanı', 'Hiereia Saray İskelesi'], 'Yenikapı\'daki Theodosius Limanı kazıları, Orta Çağ gemiciliğinde kabuktan iskelet temelli üretime geçiş sürecini aydınlatan dünyanın en geniş batık koleksiyonunu sunmuştur.'),
  ('Çin\'de Song Hanedanı döneminde (11. yüzyıl) mıknatıslı iğnenin su dolu kapta yüzdürülmesiyle açık deniz seyrüseferinde ilk kez sistematik olarak kullanılmaya başlanan alet nedir?', 'Manyetik pusula', ['Deniz kronometresi', 'Aynalı sekstant', 'Cıvalı barometre'], 'Shen Kuo ve Zhu Yu\'nun metinlerinde anlatılan manyetik pusula, Çinli denizcilerden İslam dünyasına ve oradan Akdeniz gemicilerine aktarılmıştır.'),
  ('Girit ile Mora arasındaki küçük bir ada açıklarında MÖ 1. yüzyılda batan bir Roma yük gemisinden çıkarılan ve gök cisimlerinin hareketlerini hesaplayan dişli çarklı bronz düzenek hangisidir?', 'Antikythera Düzeneği', ['İskenderiye Usturlabı', 'Rodos Güneş Saati', 'Arşimet Burgu Pompası'], '1901\'de sünger avcılarınca bulunan Antikythera Batığı\'ndan çıkarılan bu mekanizma, bilinen en eski analog astronomi bilgisayarı kabul edilir.'),
  ('Batı dillerindeki \'Admiral\' (Amiral) sözcüğünün etimolojik olarak Orta Çağ Akdeniz denizciliğinde hangi Arapça unvandan türediği kabul edilmektedir?', 'Emîrü\'l-bahr', ['Reîsü\'l-küttâb', 'Melikü\'s-sevâhil', 'Sahibü\'ş-şurta'], 'Arapça \'Emîrü\'l-bahr\' (veya Emirü\'l-mâ) unvanı, Sicilya Normanları ve Cenevizliler aracılığıyla \'Amiratus / Admiral\' biçiminde Avrupa dillerine yerleşmiştir.'),
  ('Savaş ve ticaret gemilerinde suyun derinliğini ve deniz tabanının kumlu ya da kayalık yapısını anlamak için altına içyağı sürülmüş kurşun ağırlıklı ipin sarkıtılması yöntemine ne denir?', 'İskandil', ['Parakete', 'Bodoslama', 'Armuz'], 'Antik Çağ\'dan beri kullanılan iskandil kurşunu, hem kulaç cinsinden derinliği ölçer hem de altındaki yağa yapışan tortudan dip yapısını belli ederdi.'),
  ('1405-1433 yılları arasında Ming Hanedanı adına yedi büyük okyanus seferi düzenleyerek Güneydoğu Asya, Hindistan, Hürmüz ve Doğu Afrika kıyılarına dek ulaşan Çinli Müslüman amiral kimdir?', 'Zheng He', ['Kubilay Han', 'Sun Tzu', 'Zhang Qian'], 'Zheng He (Hacı Mahmud Şemseddin), yüzlerce gemiden ve dev \'hazine gemilerinden\' oluşan filolarla Hint Okyanusu\'nda diplomatik ve ticari güç gösterisi yapmıştır.'),
  ('Portekiz\'in güney ucundaki Sagres\'te haritacıları, gökbilimcileri ve gemi ustalarını bir araya getirerek Batı Afrika kıyılarının sistemli keşfini başlatan hanedan üyesi kimdir?', 'Gemici Henrique', ['Kral I. Manuel', 'Vasco da Gama', 'Afonso de Albuquerque'], 'Prens Gemici Henrique bizzat okyanus seferlerine çıkmasa da Portekiz denizciliğinin kurumsal ve teknik altyapısını kurarak Coğrafi Keşifler\'i başlatmıştır.'),
  ('15. yüzyılda Portekizlilerin Batı Afrika açıklarında ters rüzgârlara karşı seyir yapabilmek için geliştirdikleri, hafif gövdeli ve iki ya da üç direğinde Latin yelken taşıyan gemi türü hangisidir?', 'Karavela', ['Üç ambarlı kalyon', 'Çift sıra kürekli kadırga', 'Buharlı yandan çarklı korvet'], 'Karavela, sığ kıyı sularına girebilmesi ve rüzgâra dar açıyla ilerleyebilmesi sayesinde Bartolomeu Dias ile Kolomb\'un ilk keşiflerinde kilit rol oynamıştır.'),
  ('Güneş\'in veya Kutup Yıldızı\'nın ufuk düzlemiyle yaptığı açıyı ölçerek açık denizde geminin hangi enlem derecesinde bulunduğunu hesaplamaya yarayan halka biçimli seyir aleti nedir?', 'Denizci usturlabı', ['Aneroid barometre', 'Manyetik inklinometre', 'İskandil ağırlık kurşunu'], 'İslam astronomlarından İber yarımadasına geçen usturlap, rüzgârın etkisini azaltmak için ağır pirinçten delikli halka şeklinde denizciliğe uyarlanmıştır.'),
  ('1488 yılında Afrika kıtasının güney ucunu fırtınalar içinde dolaşarak Hint Okyanusu ile Atlas Okyanusu\'nun birleştiğini kanıtlayan ve buraya \'Fırtınalar Burnu\' adını veren Portekizli denizci kimdir?', 'Bartolomeu Dias', ['Pedro Álvares Cabral', 'Fernão de Magalhães', 'Diogo Cão'], 'Bartolomeu Dias\'ın Fırtınalar Burnu olarak adlandırdığı geçit, Hindistan yolunun açılması ümidiyle Portekiz Kralı II. João tarafından Ümit Burnu\'na çevrilmiştir.'),
  ('1492 yılında batıya doğru yelken açarak Asya\'ya ulaşmak isterken Bahamalar\'daki San Salvador Adası\'na varan Kristof Kolomb\'un sancak gemisi olan karaka tipi tekne hangisidir?', 'Santa Maria', ['Golden Hind', 'Trinidad', 'Endeavour'], 'Kolomb ilk seferine Santa Maria adlı karaka (nau) ve daha küçük boyutlu Niña ile Pinta adlı iki karavelayla Palos Limanı\'ndan çıkmıştır.'),
  ('1494 yılında Papa VI. Alexander\'ın hakemliğinde İspanya ve Portekiz arasında imzalanarak yeni keşfedilen okyanusları Yeşil Burun Adaları\'nın 370 fersah batısındaki meridyenle ikiye ayıran antlaşma hangisidir?', 'Tordesillas Antlaşması', ['Vestfalya Antlaşması', 'Pireneler Antlaşması', 'Utrecht Antlaşması'], 'Tordesillas Antlaşması uyarınca sınır çizgisinin doğusu Portekiz\'e (Afrika, Hindistan yolu ve Brezilya ucu), batısı ise İspanya\'ya bırakılmıştır.'),
  ('1497-1498 yıllarında Ümit Burnu\'nu dolaşıp Doğu Afrika\'daki Malindi limanından yerel kılavuz alarak Hindistan\'ın Kalküta (Kozhikode) limanına deniz yoluyla ulaşan ilk Avrupalı kimdir?', 'Vasco da Gama', ['Amerigo Vespucci', 'Hernán Cortés', 'Giovanni Caboto'], 'Vasco da Gama\'nın Kalküta\'ya ulaşması, Venedik ve Memlûklerin elindeki geleneksel Akdeniz baharat ticaret yoluna doğrudan alternatif yaratmıştır.'),
  ('Kolomb\'un Asya\'nın doğu kıyıları sandığı toprakların aslında Avrupalılarca bilinmeyen ayrı bir \'Yeni Dünya\' (Mundus Novus) kıtası olduğunu yayımladığı mektuplarla ortaya koyan Floransalı denizci kimdir?', 'Amerigo Vespucci', ['Paolo Toscanelli', 'Giovanni da Verrazzano', 'Sebastiano Caboto'], 'Alman haritacı Martin Waldseemüller, 1507 tarihli dünya haritasında Vespucci\'nin tespitlerine dayanarak yeni kıtaya \'America\' adını vermiştir.'),
  ('1577-1580 yılları arasında \'Golden Hind\' adlı kalyonuyla İspanyol limanlarına baskınlar düzenleyerek Macellan-Elcano\'dan sonra dünya çevresini dolaşan ikinci kaptan olan İngiliz denizci kimdir?', 'Francis Drake', ['Horatio Nelson', 'Robert Blake', 'George Anson'], 'Kraliçe I. Elizabeth tarafından bizzat kendi gemisinin güvertesinde şövalye ilan edilen Francis Drake, Pasifik\'teki İspanyol gümüş gemilerini ele geçirmiştir.'),
  ('16. yüzyılda okyanus aşırı hem ağır topçu bataryaları hem de değerli maden taşımak üzere geliştirilen, karakaya göre daha alçak baş kasarası ve uzun gövdesiyle öne çıkan çok direkli gemi hangisidir?', 'Kalyon', ['Çektiri', 'Kancabaş', 'Karamürsel'], 'İspanyol Hazine Filosu\'nun ve İngiliz donanmasının ana unsuru olan kalyonlar, yelkenli savaş gemisi (hat gemisi) mimarisinin öncüsü olmuştur.'),
  ('1569 yılında yayımladığı dünya haritasında meridyen ve paralelleri dik kesişen düz çizgiler halinde açarak denizcilerin sabit pusula açısıyla (kerte hattı) rota çizmesini kolaylaştıran Flaman haritacı kimdir?', 'Gerardus Mercator', ['Abraham Ortelius', 'Petrus Plancius', 'Willem Blaeu'], 'Mercator projeksiyonu kutuplara gidildikçe alanları büyütse de açıları koruduğu (konform olduğu) için açık deniz navigasyonunda standart harita yöntemi olmuştur.'),
  ('Uzun okyanus yolculuklarında taze sebze ve meyve eksikliğinden kaynaklanan C vitamini yetersizliği sonucu diş eti kanaması ve halsizlikle binlerce denizcinin ölümüne yol açan hastalık nedir?', 'İskorbüt', ['Sıtma', 'Beriberi', 'Tifüs'], 'Keşif Çağı\'nda savaşlardan daha fazla denizcinin ölümüne neden olan iskorbüt, İskoç deniz hekimi James Lind\'in 1747\'deki narenciye deneyiyle çözüme kavuşmuştur.'),
  ('18. yüzyıl ortalarında usturlap ve Yakup çubuğunun yerini alan, çift yansıtmalı aynalarıyla ufuk çizgisi ile gök cismini aynı görüş alanında çakıştırarak 120 dereceye kadar açı ölçebilen seyir aleti nedir?', 'Sekstant', ['Teodolit', 'Batimetre', 'Anemometre'], '60 derecelik yay dilimine (dairenin altıda biri) sahip olduğu için Sekstant adını alan alet, sallanan güvertede bile yüksek hassasiyetli açı ölçümü sağlamıştır.'),
  ('1768-1779 yılları arasında yaptığı üç büyük Pasifik seferiyle Yeni Zelanda\'yı ve Avustralya\'nın doğu kıyılarını haritalandıran, Antarktika Dairesi\'ni ilk kez aşan İngiliz kaptan kimdir?', 'James Cook', ['Matthew Flinders', 'William Bligh', 'George Vancouver'], 'Kaptan James Cook, HMS Endeavour ve HMS Resolution gemileriyle Pasifik coğrafyasındaki boşlukları doldurmuş, lahana turşusu ve hijyenle iskorbütü engellemiştir.'),
  ('1831-1836 yılları arasında Kaptan Robert FitzRoy komutasında Güney Amerika kıyılarını ve Galapagos Adaları\'nı haritalandırırken genç doğa bilimci Charles Darwin\'i taşıyan araştırma gemisi hangisidir?', 'HMS Beagle', ['HMS Challenger', 'Calypso', 'Fram'], 'Kraliyet Donanması\'na ait HMS Beagle araştırma brikinin beş yıllık dünya seferi, hem hidrografiye hem de biyoloji tarihine yön vermiştir.'),
  ('1807 yılında Hudson Nehri üzerinde New York ile Albany arasında düzenli yolcu taşıyarak ticari anlamda ilk başarılı buharlı gemi işletmeciliğini (\'Clermont\' vapuruyla) başlatan Amerikalı mucit kimdir?', 'Robert Fulton', ['James Watt', 'George Stephenson', 'Eli Whitney'], 'Fulton ayrıca Napolyon için \'Nautilus\' adlı insan gücüyle çalışan erken dönem bir denizaltı prototipi de tasarlamıştır.'),
  ('Güney Amerika\'nın en güney ucundaki Ateş Toprakları (Tierra del Fuego) ile Antarktika Yarımadası arasında yer alan, dünyanın en sert fırtına ve dev dalgalarıyla ünlü okyanus boğazı hangisidir?', 'Drake Geçidi', ['Mozambik Kanalı', 'Malakka Boğazı', 'Bass Boğazı'], 'Horn Burnu\'nun güneyinde Atlas ve Büyük Okyanus\'u birleştiren yaklaşık 800 km genişliğindeki su yolu, 1578\'de güneye sürüklenen Francis Drake\'in adıyla anılır.'),
  ('Yeni Zelanda\'nın Kuzey Adası ile Güney Adası\'nı birbirinden ayıran ve şiddetli gelgit akıntılarıyla bilinen boğaz hangi kâşifin adını taşır?', 'Cook Boğazı', ['Tasman Boğazı', 'Magellan Boğazı', 'Cabot Boğazı'], 'Abel Tasman burayı kapalı bir körfez sanmış, 1770 yılında Kaptan James Cook iki ada arasından gemisiyle geçerek boğaz olduğunu ortaya koymuştur.'),
  ('Atlantik köle ticaretinde Avrupa limanlarından Batı Afrika\'ya mamul mal, Afrika\'dan Amerika\'ya köle, Amerika\'dan Avrupa\'ya şeker, pamuk ve tütün taşınmasına dayanan deniz ticaret ağına ne ad verilir?', 'Üçgen Ticaret', ['Kraliyet Kervan Sistemi', 'Muson Takas Hattı', 'Serbest Liman Rejimi'], '16. ve 19. yüzyıllar arasında işleyen Atlantik Üçgen Ticareti\'nin Afrika\'dan Amerika\'ya uzanan insanlık dışı deniz etabına \'Orta Geçit\' (Middle Passage) denilmiştir.'),
  ('1943 yılında Emile Gagnon ile birlikte basınç regülatörlü tüplü dalış sistemini (Aqua-Lung) icat ederek sualtı araştırmalarını ve deniz belgeselciliğini yaygınlaştıran \'Calypso\' gemisi kaptanı kimdir?', 'Jacques-Yves Cousteau', ['Robert Ballard', 'Sylvia Earle', 'Jean-Michel Cousteau'], 'Eski bir mayın tarama gemisi olan Calypso\'yu oşinografi gemisine çeviren Cousteau, \'Sessiz Dünya\' yapıtı ve dalış regülatörüyle modern sualtı dünyasının öncüsü olmuştur.'),
  ('1081 yılında İzmir ve çevresinde bağımsız bir beylik kurarak 50 parçalık ilk Türk donanmasını inşa ettiren ve kuruluş yılı Türk Deniz Kuvvetleri\'nin başlangıcı kabul edilen denizci kimdir?', 'Çaka Bey', ['Artuk Bey', 'Saltuk Bey', 'Danişmend Gazi'], 'Bizans sarayında esaret yıllarında denizciliği yakından tanıyan Çaka Bey, 1081\'de İzmir\'de ilk Türk donanmasını kurarak Midilli, Sakız ve Sisam adalarını fethetmiştir.'),
  ('Anadolu Selçuklu Sultanı I. İzzeddin Keykavus\'un 1214 yılında fethederek Karadeniz\'deki ilk Selçuklu tersanesini kurduğu ve İtalyan tüccarlara açtığı liman kenti hangisidir?', 'Sinop', ['Samsun', 'Trabzon', 'Amasra'], 'Trabzon Rum İmparatorluğu\'ndan alınan Sinop\'ta tersane inşa edilmiş, iç kaleye fetih kitabeleri konularak Karadeniz ticaret yolu güvenceye alınmıştır.'),
  ('I. Alaeddin Keykubad\'ın 1221 yılında Kalonoros Kalesi\'ni fethederek kendi adıyla yeniden imar ettiği ve günümüze ulaşan beş gözlü taş tersaneyi inşa ettirdiği Akdeniz kenti neresidir?', 'Alanya (Alâiye)', ['Mersin (İçel)', 'İskenderun', 'Fethiye (Meğri)'], 'Alanya Tersanesi ve onu koruyan Kızılkule ile birlikte Sultan Alaeddin Keykubad \'Sultanü\'l-Bahreyn\' (İki Denizin Sultanı) unvanını kullanmıştır.'),
  ('Orhan Gazi döneminde Osmanlı Devleti\'ne katılan ve Edincik, Gemlik, Çanakkale kıyılarındaki gemi tezgâhları ile yetişmiş denizcilerini Osmanlı\'ya miras bırakan ilk Anadolu beyliği hangisidir?', 'Karesioğulları Beyliği', ['Menteşeoğulları Beyliği', 'Saruhanoğulları Beyliği', 'Candaroğulları Beyliği'], 'Karesioğulları\'nın ilhakıyla Hacı İlbeyi, Evrenos Bey ve Ece Yakup gibi deniz-boğaz geçiş tecrübesine sahip komutanlar Osmanlıların Rumeli\'ye geçişini hızlandırmıştır.'),
  ('1327 yılında İzmit Körfezi\'nin güney kıyısında ilk Osmanlı tersanesini kurarak Osmanlı donanmasının çekirdeğini oluşturan ve geliştirdiği hızlı hafif çektiri tipine adını veren komutan kimdir?', 'Karamürsel Alp', ['Konur Alp', 'Akçakoca', 'Abdurrahman Gazi'], 'Karamürsel Alp Osmanlı\'nın ilk \'Derya Beyi\' kabul edilir; Marmara taşımacılığında yüzyıllarca kullanılan \'Karamürsel\' tipi tekne onun adıyla anılmıştır.'),
  ('Yıldırım Bayezid döneminde 1390 yılı civarında Çanakkale Boğazı girişini denetlemek amacıyla ilk büyük ve teşkilatlı Osmanlı deniz üssünün Saruca Paşa tarafından kurulduğu yer neresidir?', 'Gelibolu', ['Tekirdağ', 'Mudanya', 'Ereğli'], 'Gelibolu Sancağı uzun yıllar Kaptan-ı Derya\'nın \'paşa sancağı\' statüsünü korumuş ve Haliç Tersanesi büyüyene dek Osmanlı donanmasının ana üssü olmuştur.'),
  ('İstanbul\'un fethinden sonra Fatih Sultan Mehmed\'in Haliç\'teki Aynalıkavak-Kasımpaşa kıyısında birkaç gözlü kızak ve divanhaneyle temelini attığı merkez tersane hangisidir?', 'Tersâne-i Âmire', ['Tophâne-i Âmire', 'İstinye Kalafat Yeri', 'Beşiktaş Hayrettin İskelesi'], 'Fatih devrinde kurulan, Yavuz Sultan Selim ve Kanuni dönemlerinde yüzlerce göze çıkarılan Haliç Tersâne-i Âmire\'si imparatorluğun en büyük sanayi ve gemi inşa merkeziydi.'),
  ('Fatih Sultan Mehmed döneminde 1475\'te Kırım sahillerindeki Ceneviz kalelerini fetheden ve 1480\'de Güney İtalya\'nın topuğundaki Otranto Kalesi\'ne denizden çıkarma yapan veziriazam ve komutan kimdir?', 'Gedik Ahmet Paşa', ['Mahmut Paşa', 'İshak Paşa', 'Hersekzade Ahmet Paşa'], 'Gedik Ahmet Paşa hem Karadeniz\'in Türk gölü haline gelmesinde hem de Adriyatik ağzındaki Otranto Seferi\'yle İtalya harekâtında başrolü üstlenmiştir.'),
  ('II. Bayezid\'in davetiyle 1495\'te Osmanlı devlet hizmetine giren, öncesinde Endülüs\'teki Müslüman ve Yahudileri İspanya zulmünden Kuzey Afrika\'ya taşıyan ünlü Türk denizcisi kimdir?', 'Kemal Reis', ['Murat Reis', 'Uluç Hasan Paşa', 'Mezomorto Hüseyin Paşa'], 'Piri Reis\'in amcası olan Kemal Reis, açık deniz tecrübesini Osmanlı donanmasına taşıyarak II. Bayezid devrinde büyük gövdeli \'göke\' gemilerinin inşasına öncülük etmiştir.'),
  ('Gelibolulu Pîrî Reis\'in 1513 yılında ceylan derisi üzerine çizip 1517\'de Mısır Seferi sırasında Yavuz Sultan Selim\'e sunduğu ilk dünya haritasının günümüze ulaşan parçası hangi bölgeleri gösterir?', 'İber Yarımadası, Batı Afrika ve Amerika\'nın doğu kıyılarını', ['Japon Takımadaları, Kore Yarımadası ve Avustralya sahillerini', 'İskandinav Fiyortları, Baltık Denizi ve Sibirya buzullarını', 'Basra Körfezi, Seylan Adası ve Malakka Boğazı\'nı'], '1929 yılında Topkapı Sarayı\'nda bulunan 1513 Pîrî Reis Haritası parçası, Kolomb\'un kayıp haritalarından da yararlanarak Orta ve Güney Amerika kıyılarını gösteren en eski haritalardandır.'),
  ('Pîrî Reis\'in Akdeniz\'deki tüm limanları, tatlı su kaynaklarını, sığlıkları ve rüzgârları ayrıntılı haritalar eşliğinde anlattığı, 1526\'da Sadrazam İbrahim Paşa aracılığıyla Kanuni\'ye sunduğu başyapıtı hangisidir?', 'Kitâb-ı Bahriye', ['Mir\'âtü\'l-Memâlik', 'Cihannümâ', 'Tuhfetü\'l-Kibâr fî Esfâri\'l-Bihâr'], 'Dünya denizcilik tarihinin en kapsamlı kılavuz (portolan) atlaslarından biri olan Kitâb-ı Bahriye, Ege ve Akdeniz kıyı coğrafyasını birebir gözlemlerle belgelemiştir.'),
  ('Midilli Adası\'nda doğup kardeşi Hızır Reis ile birlikte Batı Akdeniz\'de İspanyollara karşı mücadele ederek Cezayir\'de bağımsız bir Türk deniz idaresi kuran ve 1518\'de Tlemsen yakınlarında şehit düşen denizci kimdir?', 'Oruç Reis', ['Salih Reis', 'İlyas Reis', 'Sinan Reis'], 'Avrupalıların kızıl sakalından ötürü ilk kez \'Barbarossa\' adını verdikleri Oruç Reis, Rodos Şövalyeleri\'ne esir düştükten sonra kurtulup Cezayir\'i İspanyol işgalinden kurtarmıştır.'),
  ('1533 yılında Kanuni Sultan Süleyman\'ın davetiyle İstanbul\'a gelerek Cezayir\'i Osmanlı topraklarına katan ve ilk kez \'Cezayir Beylerbeyi ve Kaptan-ı Derya\' unvanıyla Divan-ı Hümayun üyesi olan denizci kimdir?', 'Barbaros Hayrettin Paşa', ['Sokullu Mehmet Paşa', 'Lütfi Paşa', 'Rüstem Paşa'], 'Asıl adı Hızır olan ve Kanuni tarafından \'dinin hayırlısı\' anlamında \'Hayrettin\' unvanı verilen Barbaros, Osmanlı donanmasını dünya çapında birinci güce çıkarmıştır.'),
  ('27-28 Eylül 1538\'de Yunanistan\'ın batısında Barbaros Hayrettin Paşa\'nın kalyon ağırlıklı kalabalık Haçlı donanmasını hilal düzeni ve rüzgârsız havada kadırga manevrasıyla bozguna uğrattığı zafer hangisidir?', 'Preveze Deniz Zaferi', ['Cerbe Deniz Zaferi', 'İnebahtı Deniz Savaşı', 'Çeşme Deniz Baskını'], 'Cenevizli Amiral Andrea Doria komutasındaki Haçlı birleşik donanmasına karşı kazanılan Preveze Zaferi ile Akdeniz\'de uzun süreli Osmanlı deniz üstünlüğü tescillenmiştir.'),
  ('1560 yılında Tunus açıklarında Piyale Paşa ve Turgut Reis komutasındaki Osmanlı donanmasının İspanya öncülüğündeki Haçlı donanmasını ve adadaki kaleyi ele geçirerek Kuzey Afrika hâkimiyetini perçinlediği zafer hangisidir?', 'Cerbe Deniz Zaferi', ['Otranto Çıkarması', 'Sapienza Savaşı', 'Navarin Baskını'], 'Medinaceli Dükü komutasındaki Haçlı filosunun yaklaşık yarısının batırılıp ele geçirildiği Cerbe Zaferi, Osmanlı deniz gücünün Batı Akdeniz\'deki zirve noktasıdır.'),
  ('Kanuni Sultan Süleyman ve Yavuz dönemlerinden itibaren Portekizlilerin Kızıldeniz ve Basra Körfezi\'ni kapatarak Hint baharat ticaretini engellemesine karşı Osmanlı Devleti\'nin 1538-1553 arasında yürüttüğü harekâtlar bütünü nedir?', 'Hint Deniz Seferleri', ['Lehistan Boğdan Seferleri', 'Fas Vadisseyl Harekâtı', 'Girit Kandiye Kuşatması'], 'Hadım Süleyman Paşa, Pîrî Reis, Murad Reis ve Seydi Ali Reis komutasında dört büyük sefer düzenlenmiş; Kızıldeniz, Yemen ve Habeş kıyıları korunsa da okyanusta Portekiz kalyonlarına üstünlük kurulamamıştır.'),
  ('Seydi Ali Reis\'in Hindistan\'dan İstanbul\'a uzanan maceralı dönüş yolculuğunda gördüğü ülkeleri, hükümdarları ve kültürleri anlattığı Türk edebiyatının ilk gezi kitaplarından sayılan eseri hangisidir?', 'Mir\'âtü\'l-Memâlik (Memleketlerin Aynası)', ['Kitâb-ı Bahriye (Denizcilik Kitabı)', 'Seyahatnâme', 'Babürnâme'], 'Mir\'âtü\'l-Memâlik\'in yanı sıra Seydi Ali Reis, Hint Okyanusu astronomi ve seyir bilgilerini içeren \'Kitâbü\'l-Muhît\' adlı değerli bir okyanus kılavuzu da yazmıştır.'),
  ('Klasik Dönem Osmanlı donanmasında hem kürek hem yardımcı Latin yelkenle hareket eden, uzun ve alçak gövdeli savaş gemilerinin genel sınıf adı aşağıdakilerden hangisidir?', 'Çektiri', ['Zırhlı', 'Uskuna', 'Brik'], 'Osmanlı donanması 17. yüzyıl ortalarına kadar çektiri sınıfı (kadırga, baştarda, kalite, kalyata, fırkata, mavna) gemileri ana vurucu güç olarak kullanmıştır.'),
  ('Klasik Osmanlı bahriyesinde Cezayir, Tunus ve Trablusgarp\'ta üslenerek Batı Akdeniz\'de gönüllü gaza ve akın faaliyetleri yürüten denizci ocaklarına verilen ortak ad nedir?', 'Garp Ocakları', ['Enderun Odaları', 'Evlad-ı Fatihan', 'Sekban Bölükleri'], 'Cezayir, Tunus ve Trablusgarp \'Garp Ocakları\' (Dayılıklar), yarı özerk deniz filolarıyla yüzyıllar boyunca Osmanlı donanmasına usta reisler ve kalyon desteği sağlamıştır.'),
  ('1570-1571 yıllarında Lala Mustafa Paşa ve Piyale Paşa komutasındaki kara-deniz ortak harekâtıyla Venediklilerden fethedilerek Doğu Akdeniz güvenliğini tamamlayan ada hangisidir?', 'Kıbrıs', ['Girit', 'Malta', 'Sicilya'], 'Mısır ve Suriye\'den İstanbul\'a gelen deniz ticaret ve hac gemilerinin güvenliği için kritik öneme sahip olan Kıbrıs\'ın fethi, Avrupa\'da Kutsal İttifak\'ın kurulmasını tetiklemiştir.'),
  ('1571 İnebahtı Deniz Savaşı\'nda Osmanlı merkez ve sağ kanadı çökerken sol kanatta Malta Şövalyeleri\'ne ve Gianandrea Doria\'ya üstünlük sağlayıp 40\'a yakın gemisini sağlam biçimde İstanbul\'a getiren reis kimdir?', 'Uluç Ali Reis', ['Müezzinzade Ali Paşa', 'Şuluk Mehmed Paşa', 'Pertev Paşa'], 'İnebahtı\'daki üstün manevra başarısı üzerine Sultan II. Selim, Uluç Ali Reis\'in unvanını \'Kılıç\'a çevirerek onu Kaptan-ı Deryalığa atamıştır.'),
  ('İnebahtı yenilgisinden sonra Venedik elçisi Barbaro\'ya \'Biz Kıbrıs\'ı almakla sizin kolunuzu kestik, siz donanmamızı yakmakla sakalımızı tıraş ettiniz; kesilen kol yerine gelmez ama sakal daha gür çıkar\' diyen sadrazam kimdir?', 'Sokullu Mehmet Paşa', ['Pargalı İbrahim Paşa', 'Köprülü Mehmet Paşa', 'Merzifonlu Kara Mustafa Paşa'], 'Sokullu Mehmet Paşa ve Kılıç Ali Paşa\'nın olağanüstü gayretiyle tek bir kış içinde Tersâne-i Âmire ve taşra tezgâhlarında yaklaşık 200 yeni kadırga ve mavna denize indirilmiştir.'),
  ('Osmanlı donanmasında gemilerde tüfekli deniz piyadesi olarak savaşan, cesaretleri ve kendilerine özgü kıyafetleriyle tanınan deniz askerlerine verilen ad nedir?', 'Levent', ['Tımarlı sipahi', 'Humbaracı', 'Lağımcı'], 'Ege adaları ve Batı Anadolu kıyı gençlerinden toplanan deniz leventleri, bordalama savaşlarında Osmanlı kadırgalarının en etkili vurucu gücüydü.'),
  ('Fatih Sultan Mehmed döneminde Karadeniz kıyı güvenliğini ve İpek Yolu\'nun güney deniz ayağını tamamlamak üzere 1461\'de Cenevizlilerden ve Komnenoslardan alınan iki önemli liman hangileridir?', 'Amasra ve Trabzon', ['Kefe ve Azak', 'Kili ve Akkerman', 'Sinop ve Alanya'], 'Fatih 1461\'de hem donanma hem kara ordusuyla yürüttüğü koordineli harekâtla Batı Karadeniz\'deki Ceneviz üssü Amasra\'yı ve Doğu Karadeniz\'deki Trabzon\'u Osmanlı\'ya katmıştır.'),
  ('İstanbul\'un Beşiktaş semtinde Mimar Sinan tarafından türbesi inşa edilen ve Osmanlı donanmasının Akdeniz\'e sefere çıkarken önünde top atışı ve dualarla selam durma geleneğini sürdürdüğü denizci kimdir?', 'Barbaros Hayrettin Paşa', ['Kılıç Ali Paşa', 'Turgut Reis', 'Piyale Paşa'], 'Donanma-yı Hümayun her ilkbaharda Haliç\'ten çıkıp Beşiktaş önlerinde demirler, Kaptan-ı Derya ve leventler Barbaros Türbesi\'ni ziyaret ettikten sonra yelken açardı.'),
  ('İstanbul Boğazı\'nın iki yakası arasında düzenli yolcu taşımacılığı yapmak üzere 1851 yılında Sadrazam Mustafa Reşid Paşa ve Cevdet Paşa\'nın öncülüğünde kurulan Osmanlı\'nın ilk anonim vapur şirketi hangisidir?', 'Şirket-i Hayriye', ['İdare-i Mahsusa', 'Düyûn-ı Umûmiye', 'Reji İdaresi'], 'Şirket-i Hayriye, baca numaralı vapurlarıyla Boğaziçi yerleşimini dönüştürmüş ve dünyada ilk arabalı vapur örneklerinden olan \'Suhulet\' (26) gemisini 1872\'de hizmete sokmuştur.'),
  ('Sultan II. Abdülhamid döneminde Japon İmparatoru Meiji\'ye nişan ve hediyeler götürdükten sonra dönüş yolunda 16 Eylül 1890 gecesi Wakayama\'daki Kuşimoto kayalıklarında tayfuna yakalanarak batan Osmanlı gemisi hangisidir?', 'Ertuğrul Fırkateyni', ['Hamidiye Kruvazörü', 'Muavenet-i Milliye Muhribi', 'Mesudiye Zırhlısı'], 'Osman Paşa komutasındaki Ertuğrul Fırkateyni\'nden 500\'ü aşkın denizci şehit düşerken, Kuşimoto köylülerinin yaralı 69 denizciyi özveriyle kurtarması Türk-Japon dostluğunun simgesi olmuştur.'),
  ('1770 Çeşme felaketinden sonra Kasımpaşa\'da Kaptan-ı Derya Cezayirli Gazi Hasan Paşa\'nın ve Baron de Tott\'un girişimleriyle 1773\'te modern deniz subayı yetiştirmek üzere açılan okulun ilk adı nedir?', 'Mühendishâne-i Bahrî-i Hümâyun', ['Mekteb-i Tıbbiye-i Şâhâne', 'Mekteb-i Mülkiye', 'Dârülfünun'], 'Günümüz Deniz Harp Okulu ve İstanbul Teknik Üniversitesi\'nin çekirdeğini oluşturan Mühendishâne-i Bahrî-i Hümâyun, Haliç\'te Hendesehane adıyla eğitime başlamıştır.'),
  ('Halk bağışlarıyla İngiltere\'deki Vickers ve Armstrong tersanelerine parası peşin ödenerek sipariş edilen, ancak I. Dünya Savaşı patlak verince Ağustos 1914\'te İngiliz Bahriye Nazırı Churchill tarafından el konulan iki Türk dretnotu hangileridir?', 'Sultan Osman-ı Evvel ve Reşadiye', ['Yavuz ve Midilli', 'Turgut Reis ve Barbaros Hayreddin', 'Mecidiye ve Hamidiye'], 'İnşası bitmiş olan Sultan Osman ve Reşadiye zırhlılarına İngiltere\'nin bedelini ödemeden el koyması Osmanlı kamuoyunda büyük infial yaratmış ve Goeben-Breslau\'nun kabulüne zemin hazırlamıştır.'),
  ('1588 yılında İspanya Kralı II. Felipe\'nin Katolikliği yeniden tesis etmek ve İngiliz korsanlığını bitirmek amacıyla Manş Denizi\'ne gönderdiği, ancak ateş gemileri ve fırtınalarla dağılan dev filo tarihte nasıl anılır?', 'Yenilmez Armada', ['Kutsal Akdeniz Haçlı Donanması', 'Büyük Doğu Hindistan Konvoyu', 'Gümüş Hazine Kalyon Filosu'], 'Medina Sidonia Dükü komutasındaki İspanyol Yenilmez Armadası, Gravelines açıklarında çevik İngiliz kalyonlarının uzun menzilli topçusu ve İskoçya-İrlanda fırtınalarıyla ağır kayba uğramıştır.'),
  ('1768-1774 Osmanlı-Rus Savaşı sırasında Rus Baltık Filosu\'nun İngiltere\'nin lojistik desteğiyle Cebelitarık Boğazı\'ndan Akdeniz\'e girip 1770 gecesi ateş gemileriyle Osmanlı donanmasını yaktığı yer neresidir?', 'Çeşme Limanı', ['Sinop İç Limanı', 'İnebahtı Körfezi', 'Preveze Boğazı'], 'Mandalzade Hüsameddin Paşa\'nın gemileri manevra yapılamayacak kadar dar Çeşme koyuna sıkıştırması üzerine Amiral Spiridov ve Kont Orlov\'un filosu Osmanlı donanmasını ateşe vermiştir.'),
  ('1 Ağustos 1798\'de Napolyon Bonapart\'ın Mısır Seferi ordusunu taşıyan Fransız donanmasını İskenderiye yakınlarında gece baskınıyla kıyı ile kendi gemileri arasında iki ateş arasına alarak yok eden İngiliz amirali kimdir?', 'Horatio Nelson', ['Cuthbert Collingwood', 'John Jellicoe', 'Andrew Cunningham'], 'Abukir (Nil) Deniz Muharebesi\'nde Fransız sancak gemisi L\'Orient\'in havaya uçmasıyla Napolyon\'un ordusu Mısır\'da Fransa ile deniz bağlantısı kesilmiş biçimde mahsur kalmıştır.'),
  ('21 Ekim 1805\'te İspanya\'nın güneybatısında Amiral Horatio Nelson\'ın geleneksel paralel hat düzenini terk edip iki dikey kol halinde Fransız-İspanyol hattını yararak kazandığı ve İngiltere\'ye yüzyıllık okyanus üstünlüğü getiren savaş hangisidir?', 'Trafalgar Deniz Muharebesi', ['Kopenhag Deniz Muharebesi', 'Jutland Deniz Muharebesi', 'Koronel Deniz Muharebesi'], 'Sancak gemisi HMS Victory\'nin direğine \'İngiltere herkesin görevini yapmasını bekliyor\' işaretini çektiren Nelson, Amiral Villeneuve\'ün birleşik filosunu çökertirken güvertede vurularak ölmüştür.'),
  ('Yunan İsyanı sırasında 20 Ekim 1827\'de İngiltere, Fransa ve Rusya\'dan oluşan müttefik donanmasının savaş ilanı olmaksızın Mora\'daki limana girerek Osmanlı-Mısır birleşik donanmasını imha ettiği olay hangisidir?', 'Navarin Baskını', ['Çeşme Vakası', 'Sinop Baskını', 'Otranto Seferi'], 'Navarin Baskını tarihte tamamen yelkenli ahşap hat gemileriyle yapılan son büyük deniz muharebesi olmuş; Osmanlı Devleti donanmasız kalarak 1828-1829 Rus Savaşı\'na savunmasız girmiştir.'),
  ('Kırım Savaşı başlarında 30 Kasım 1853\'te Rus Amiral Pavel Nahimov\'un fırtınadan korunmak için limana sığınan Osmanlı filosunu yeni tip patlayıcı \'Paixhans\' gülleleriyle yakarak Avrupa\'nın savaşa girmesini tetiklediği olay nedir?', 'Sinop Baskını', ['Sivastopol Kuşatması', 'Kinburn Bombardımanı', 'Preveze Çarpışması'], 'Sinop Deniz Baskını, içi patlayıcı dolu güllelerin ahşap gemileri dakikalar içinde kül ettiğini kanıtlayarak zırhlı savaş gemilerinin (ironclad) doğuşunu zorunlu kılmıştır.'),
  ('Birinci Balkan Savaşı\'nda (1912-1913) Yunan zırhlısı \'Averof\'un Çanakkale Boğazı\'nı abluka altına aldığı sırada boğazdan sızarak Ege, Akdeniz ve Kızıldeniz\'de 7 ay boyunca tek başına başarılı akın harekâtı yürüten Osmanlı kruvazörü ve komutanı kimdir?', 'Hamidiye Kruvazörü - Hüseyin Rauf (Orbay)', ['Mecidiye Kruvazörü - Muzaffer Adil Bey', 'Yavuz Kruvazörü - Wilhelm Souchon', 'Peyk-i Şevket - Ahmet Saffet (Ohkay)'], 'Rauf Bey komutasındaki Hamidiye, Şira Limanı\'nda Yunan yardımcı kruvazörü Makedonya\'yı batırmış ve Adriyatik\'teki Şingin Limanı\'nda Sırp ikmal gemilerini vurarak \'Hamidiye Kahramanı\' unvanını almıştır.'),
  ('Ağustos 1914\'te Akdeniz\'de İngiliz donanmasının takibinden kaçarak Çanakkale Boğazı\'ndan Osmanlı\'ya sığınan ve \'Yavuz Sultan Selim\' ile \'Midilli\' adları verilip Ekim sonunda Rus limanlarını bombalayarak Osmanlı\'yı I. Dünya Savaşı\'na sokan Alman gemileri hangileridir?', 'SMS Goeben ve SMS Breslau', ['SMS Scharnhorst ve SMS Gneisenau', 'SMS Emden ve SMS Königsberg', 'SMS Bismarck ve Prinz Eugen'], 'Amiral Wilhelm Souchon komutasındaki Goeben ve Breslau\'nun satın alındığı ilan edilmiş, 29 Ekim 1914\'te Sivastopol ve Odesa\'yı bombalamalarıyla Karadeniz\'de savaş fiilen başlamıştır.'),
  ('Çanakkale Deniz Harekâtı öncesinde 7-8 Mart 1915 gecesi Yüzbaşı Tophaneli Hakkı Bey ve Mayın Grup Komutanı Nazmi Bey yönetiminde Erenköy Koyu\'ndaki Karanlık Liman\'a kıyıya paralel 26 mayın dökerek 18 Mart zaferinin kaderini belirleyen gemi hangisidir?', 'Nusret Mayın Gemisi', ['Muavenet-i Milliye Muhribi', 'Sultanhisar Torpidobotu', 'Mesudiye Sabit Zırhlısı'], 'Düşman uçak ve tarama gemilerinin beklemediği manevra alanına dökülen Nusret mayınları, 18 Mart\'ta Bouvet, Irresistible ve Ocean zırhlılarının batmasına yol açmıştır.'),
  ('II. Dünya Savaşı\'nda 1939\'dan 1945\'e dek kesintisiz süren, Alman Amiral Karl Dönitz\'in \'kurt sürüsü\' (Rudeltaktik) denizaltı saldırılarına karşı Müttefik konvoylarının sonar, radar ve Enigma şifre çözümüyle kazandığı mücadele hangisidir?', 'Atlantik Savaşı', ['Mercan Denizi Savaşı', 'Filipin Denizi Savaşı', 'Cava Denizi Savaşı'], 'İngiltere\'nin gıda ve silah ikmal damarını kesmeyi hedefleyen Alman U-botları, 1943 baharından itibaren uzun menzilli uçaklar, eskort uçak gemileri ve HF/DF yön bulucularla etkisizleştirilmiştir.'),
  ('Mayıs 1941\'de Danimarka Boğazı\'nda İngiliz donanmasının gururu \'HMS Hood\' muharebe kruvazörünü batırdıktan üç gün sonra dümeni torpidoyla kilitlenince Kuzey Atlantik\'te İngiliz filosunca batırılan ünlü Alman zırhlısı hangisidir?', 'Bismarck', ['Admiral Graf Spee', 'Tirpitz', 'Scharnhorst'], 'HMS Ark Royal\'den kalkan uçakların attığı tek bir torpidonun Bismarck\'ın dümenini sıkıştırması, dev zırhlının İngiliz ana filosu tarafından kuşatılıp batırılmasını sağlamıştır.'),
  ('7 Aralık 1941 sabahı Japon İmparatorluk Donanması\'nın altı uçak gemisinden kaldırdığı uçaklarla ABD Pasifik Filosu\'nun Hawaii\'deki ana üssüne düzenlediği sürpriz hava-deniz baskını neresidir?', 'Pearl Harbor', ['Wake Adası', 'Guadalcanal', 'Midway Atolü'], 'Amiral Isoroku Yamamoto\'nun planladığı Pearl Harbor saldırısında ABD zırhlıları ağır darbe alsa da Amerikan uçak gemilerinin o gün limanda bulunmaması Pasifik Savaşı\'nın seyrini kurtarmıştır.'),
  ('4-7 Haziran 1942\'de Amerikan şifre çözücülerinin Japon hedefini (\'AF\') önceden tespit etmesi sayesinde Amiral Nimitz ve Spruance yönetimindeki ABD donanmasının dört Japon uçak gemisini (Akagi, Kaga, Sōryū, Hiryū) batırarak Pasifik\'te inisiyatifi ele aldığı dönüm noktası savaşı hangisidir?', 'Midway Muharebesi', ['Okinawa Deniz Harekâtı', 'Iwo Jima Çıkarması', 'Bismarck Denizi Savaşı'], 'Midway Zaferi, Japon İmparatorluk Donanması\'nın Pearl Harbor\'dan beri süren taarruz üstünlüğünü altı ayda sona erdirerek Pasifik\'teki güç dengesini tersine çevirmiştir.'),
  ('1869 yılında açılan, Akdeniz\'deki Port Said ile Kızıldeniz\'deki Süveyş limanlarını birbirine bağlayarak Avrupa-Güney Asya deniz yolunu Ümit Burnu rotasına göre yaklaşık %40 kısaltan su yolu hangisidir?', 'Süveyş Kanalı', ['Panama Kanalı', 'Kiel Kanalı', 'Korint Kanalı'], 'Süveyş Kanalı\'nın açılmasıyla Akdeniz yeniden dünya deniz ticaretinin ana damarı haline gelmiş, Doğu Akdeniz limanlarının ve Kıbrıs-Mısır hattının jeopolitik değeri katlanmıştır.'),
  ('16. yüzyılın ikinci yarısında Portekiz tehdidine karşı Akdeniz donanmasını doğrudan Kızıldeniz\'e indirebilmek için Süveyş Kıstağı\'nda kanal açma ve Karadeniz\'i Hazar\'a bağlamak için Don-Volga Kanalı projelerini gündeme getiren Osmanlı sadrazamı kimdir?', 'Sokullu Mehmet Paşa', ['Çandarlı Halil Paşa', 'Kuyucu Murat Paşa', 'Köprülü Fazıl Ahmet Paşa'], 'Sokullu Mehmet Paşa 1568\'de Mısır Beylerbeyliği\'ne ferman göndererek Akdeniz ile Kızıldeniz arasındaki mesafenin ve kanal kazılabilirliğinin ölçülmesini emretmiştir.'),
  ('1914 yılında resmen hizmete girerek Atlas Okyanusu (Karayip Denizi) ile Büyük Okyanus\'u birbirine bağlayan ve Güney Amerika\'nın Horn Burnu\'nu dolaşma zorunluluğunu ortadan kaldıran su yolu hangisidir?', 'Panama Kanalı', ['Nikaragua Kanalı', 'Macellan Geçidi', 'kaledonya Kanalı'], 'ABD\'nin 1903\'te Kolombiya\'dan ayrılan Panama ile imzaladığı Hay-Bunau-Varilla Antlaşması sonrası inşa ettiği kanal, New York - San Francisco deniz mesafesini yaklaşık 8.000 deniz mili kısaltmıştır.'),
  ('1895 yılında Alman İmparatoru II. Wilhelm döneminde açılan, Kuzey Denizi ile Baltık Denizi\'ni Yütland Yarımadası\'nın tabanından birleştirerek Danimarka boğazlarını dolaşma süresini kısaltan su yolu hangisidir?', 'Kiel Kanalı', ['Ren-Main-Tuna Kanalı', 'Mittelland Kanalı', 'Amstel Deniz Kanalı'], 'İlk açıldığında \'Kaiser-Wilhelm-Kanal\' adını taşıyan Kiel Kanalı, Alman donanmasının Danimarka sularına girmeden Baltık ile Kuzey Denizi arasında hızla kuvvet kaydırması amacıyla yapılmıştır.'),
  ('Yunanistan anakarası ile Mora (Peloponez) Yarımadası arasındaki 6,3 kilometrelik dar kireçtaşı kıstağın dik duvarlar halinde yarılmasıyla 1893\'te açılan ve Ege Denizi\'ni İyon Denizi\'ne bağlayan kanal hangisidir?', 'Korint Kanalı', ['Otranto Kanalı', 'Eğriboz Kanalı', 'Selanik Kanalı'], 'Antik Çağ\'da Tiran Periander ve Roma İmparatoru Neron\'un kazmaya girişip yarım bıraktığı Korint Kanalı, dar genişliği (yaklaşık 21-25 metre) nedeniyle günümüzde küçük tonajlı gemilere ve turistik trafiğe hizmet verir.'),
  ('Basra Körfezi\'ni Umman Denizi ve Hint Okyanusu\'na bağlayan, küresel ham petrol ile sıvılaştırılmış doğal gaz (LNG) deniz ticaretinin en hayati enerji darboğazı kabul edilen su yolu hangisidir?', 'Hürmüz Boğazı', ['Babülmendep Boğazı', 'Malakka Boğazı', 'Cebelitarık Boğazı'], 'Kuzeyinde İran, güneyinde Umman\'a bağlı Musandam Yarımadası ve BAE bulunan Hürmüz Boğazı, Kuveyt, Irak, İran, Katar ve Suudi Arabistan petrollerinin açık denize çıkış kapısıdır.'),
  ('Kızıldeniz\'i Aden Körfezi ve Hint Okyanusu\'na bağlayan, Arapçada \'Gözyaşı Kapısı\' anlamına gelen ve Süveyş Kanalı rotasının güney kilidini oluşturan stratejik boğaz hangisidir?', 'Babülmendep Boğazı', ['Kerç Boğazı', 'Palk Boğazı', 'Formoza Boğazı'], 'Asya yakasında Yemen ile Afrika yakasında Cibuti ve Eritre arasında uzanan Babülmendep Boğazı, ortasındaki Perim Adası ile iki geçiş kanalına ayrılır.'),
  ('Malay Yarımadası ile Endonezya\'nın Sumatra Adası arasında uzanan, Orta Doğu\'dan Çin, Japonya ve Güney Kore\'ye giden tanker ve konteyner gemilerinin en kısa geçiş güzergâhı olan boğaz hangisidir?', 'Malakka Boğazı', ['Bering Boğazı', 'Macellan Boğazı', 'Mozambik Kanalı'], 'Güney ucunda Singapur Limanı\'nın yer aldığı Malakka Boğazı, Hint Okyanusu ile Pasifik Okyanusu (Güney Çin Denizi) arasındaki küresel ticaretin kilit koridorudur.'),
  ('Büyük Britanya Adası ile Kıta Avrupası (Fransa) arasındaki Manş Denizi\'nin en dar yerini (yaklaşık 33 km) oluşturan ve dünyanın en yoğun deniz trafik ayrım düzenlerinden birine sahip boğaz hangisidir?', 'Dover (Pas de Calais) Boğazı', ['Saint George Kanalı', 'Kuzey İrlanda Kanalı', 'Cebelitarık Boğazı'], 'Fransızcada \'Pas de Calais\', İngilizcede \'Strait of Dover\' olarak anılan boğaz, Kuzey Denizi limanlarını (Rotterdam, Anvers, Hamburg) Atlas Okyanusu\'na bağlar.'),
  ('Güney Amerika\'nın güney ucunda anakara ile Ateş Toprakları (Tierra del Fuego) adaları arasında kıvrılarak uzanan, Drake Geçidi\'ne göre daha korunaklı fakat dar ve akıntılı doğal su yolu hangisidir?', 'Macellan Boğazı', ['Bering Boğazı', 'Torres Boğazı', 'Mozambik Kanalı'], '1520\'de Ferdinand Macellan tarafından geçilen ve Şili egemenliğinde uluslararası seyrüsefere açık olan boğaz, Panama Kanalı açılana dek Atlantik-Pasifik geçişinde kritik rol oynamıştır.'),
  ('Mısır Valisi Kavalalı Mehmet Ali Paşa\'nın ordularının Kütahya\'ya kadar ilerlemesi üzerine \'denize düşen yılana sarılır\' diyerek Rusya\'dan yardım isteyen II. Mahmud\'un 1833\'te imzaladığı ve Boğazlar Sorunu\'nu uluslararası krize dönüştüren antlaşma hangisidir?', 'Hünkâr İskelesi Antlaşması', ['Bükreş Antlaşması', 'Edirne Antlaşması', 'Balta Limanı Antlaşması'], 'Hünkâr İskelesi Antlaşması\'nın gizli maddesine göre Osmanlı Devleti, Rusya saldırıya uğrarsa Rusya\'nın isteğiyle Çanakkale Boğazı\'nı diğer yabancı savaş gemilerine kapatmayı taahhüt etmiştir.'),
  ('24 Temmuz 1923\'te imzalanan Lozan Barış Antlaşması\'na ek \'Lozan Boğazlar Sözleşmesi\'nin Türkiye\'nin Boğazlar üzerindeki tam egemenliğini kısıtlayan iki temel hükmü aşağıdakilerden hangisidir?', 'Boğazların her iki yakasının askerden arındırılması ve geçişlerin uluslararası Boğazlar Komisyonu\'nca denetlenmesi', ['İstanbul Limanı gümrük gelirlerinin Yunanistan\'a savaş tazminatı olarak bırakılması ve tersanelerin yıkılması', 'Türk ticaret gemilerinin Çanakkale Boğazı\'ndan geçerken İngiltere\'den yazılı izin ve kılavuz alması', 'Karadeniz\'de Türk Deniz Kuvvetleri\'nin hiçbir suüstü devriye gemisi bulunduramaması'], 'Lozan\'da Boğazlar Komisyonu başkanlığı Türkiye\'ye verilse de her iki yakada 15-20 km\'lik askersiz bölge kurulması ve Türkiye\'nin kendi boğazlarında asker bulunduramaması ciddi bir güvenlik açığı bırakmıştır.'),
  ('20 Temmuz 1936\'da İsviçre\'de imzalanarak Uluslararası Boğazlar Komisyonu\'nu kaldıran ve Türk ordusunun Boğazların her iki yakasına yeniden yerleşerek tam egemenlik kurmasını sağlayan sözleşme hangisidir?', 'Montrö Boğazlar Sözleşmesi', ['Nyon Akdeniz Korsanlık Anlaşması', 'Balkan Antantı Savunma Protokolü', 'Sadabat Paktı Deniz Ek Sözleşmesi'], 'Dışişleri Bakanı Tevfik Rüştü Aras başkanlığındaki Türk heyetinin yürüttüğü müzakerelerle imzalanan Montrö Boğazlar Sözleşmesi, Türkiye\'nin Boğazlar üzerindeki kayıtsız şartsız egemenliğini tescillemiştir.'),
  ('Akdeniz ile Kızıldeniz\'i birbirine bağlayan ve 1869 yılında gemi trafiğine açılan su yolu hangisidir?', 'Süveyş Kanalı', ['Panama Kanalı', 'Kiel Su Kanalı', 'Korint Kanalı'], 'Süveyş Kanalı, Akdeniz ile Kızıldeniz\'i doğrudan birleştirerek Avrupa ile Güney Asya arasındaki deniz yolunu büyük ölçüde kısaltmıştır.'),
  ('Süveyş Kanalı projesinin yapım imtiyazını Mısır Valisi Said Paşa\'dan alan Fransız diplomat ve girişimci kimdir?', 'Ferdinand de Lesseps', ['Gustave Eiffel', 'George Goethals', 'Philippe Bunau-Varilla'], 'Ferdinand de Lesseps, 1854 ve 1856 yıllarında aldığı imtiyazlarla Süveyş Kanalı Şirketi\'ni kurarak kanalın inşasını yönetmiştir.'),
  ('1869 yılında Süveyş Kanalı\'nın açılması dünya deniz ticaretinde öncelikle hangi coğrafi güzergahın stratejik önemini azaltmıştır?', 'Ümit Burnu Yolu', ['Macellan Boğazı', 'Bering Boğazı', 'Cebelitarık Geçidi'], 'Avrupa\'dan Hindistan\'a giden gemilerin Afrika\'nın güneyindeki Ümit Burnu\'nu dolaşma zorunluluğu Süveyş Kanalı\'nın açılmasıyla sona ermiştir.'),
  ('Atlas Okyanusu ile Büyük Okyanus\'u Orta Amerika kıstağında birbirine bağlayan ve 1914 yılında açılan su yolu hangisidir?', 'Panama Kanalı', ['Süveyş Kanalı', 'Macellan Boğazı', 'Kiel Kanalı'], 'Panama Kanalı, Karayip Denizi üzerinden Atlas Okyanusu\'nu Büyük Okyanus\'a bağlayarak Güney Amerika\'yı dolaşma zorunluluğunu ortadan kaldırmıştır.'),
  ('Panama Kanalı açılmadan önce ABD\'nin doğu kıyısındaki New York limanından batı kıyısındaki San Francisco\'ya giden bir gemi hangi burnu dolaşmak zorundaydı?', 'Horn Burnu', ['Ümit Burnu', 'Baba Burnu', 'Ümit Burnu ve Cebelitarık'], 'Panama Kanalı öncesinde Atlas Okyanusu\'ndan Büyük Okyanus\'a geçen gemiler Güney Amerika\'nın en güney ucu olan fırtınalı Horn Burnu\'nu veya Macellan Boğazı\'nı dolaşıyordu.'),
  ('Osmanlı Devleti\'nin Boğazlar üzerindeki mutlak egemenlik hakkını son kez tek başına kullanarak Rusya ile imzaladığı 1833 tarihli antlaşma hangisidir?', 'Hünkar İskelesi Antlaşması', ['Edirne Barış Antlaşması', 'Bükreş Antlaşması', 'Küçük Kaynarca Antlaşması'], '8 Temmuz 1833\'te imzalanan Hünkar İskelesi Antlaşması ile Osmanlı Devleti, Boğazlar üzerindeki egemenliğini kendi iradesiyle kullandığı son ikili antlaşmayı yapmıştır.'),
  ('Hünkar İskelesi Antlaşması\'nın sekiz yıllık süresi dolunca Boğazlara uluslararası bir statü kazandıran 1841 tarihli sözleşme hangisidir?', 'Londra Boğazlar Sözleşmesi', ['Paris Boğazlar Sözleşmesi', 'Berlin Antlaşması', 'Viyana Kongresi Senendi'], '13 Temmuz 1841\'de imzalanan Londra Boğazlar Sözleşmesi ile Boğazlar sorunu uluslararası bir statüye bağlanmıştır.'),
  ('Birinci Dünya Savaşı sonunda Osmanlı Devleti ile İtilaf Devletleri arasında imzalanan 30 Ekim 1918 tarihli hangi ateşkes belgesiyle Çanakkale ve İstanbul Boğazlarının açılması ve istihkamlarının işgali kararlaştırılmıştır?', 'Mondros Ateşkes Antlaşması', ['Mudanya Ateşkes Antlaşması', 'Sevr Barış Antlaşması', 'Brest-Litovsk Antlaşması'], 'Mondros Ateşkes Antlaşması\'nın ilk maddesi, Karadeniz\'e geçişin serbest bırakılmasını ve Çanakkale ile Karadeniz istihkamlarının İtilaf Devletleri tarafından işgalini içermiştir.'),
  ('24 Temmuz 1923 tarihli Lozan Barış Antlaşması\'na ek olarak imzalanan Lozan Boğazlar Sözleşmesi\'ne göre kurulan Boğazlar Komisyonu\'nun başkanı hangi ülkenin temsilcisi olmuştur?', 'Türkiye', ['Birleşik Krallık', 'Fransa', 'İsviçre'], 'Sevr\'den farklı olarak Lozan Boğazlar Sözleşmesi\'nde Milletler Cemiyeti gözetiminde kurulan Boğazlar Komisyonu\'nun başkanlığı Türkiye\'ye verilmiştir.'),
  ('Türkiye\'nin Boğazlar üzerindeki tam egemenliğini yeniden kurduğu Montrö Boğazlar Sözleşmesi hangi tarihte imzalanmıştır?', '20 Temmuz 1936', ['24 Temmuz 1923', '29 Ekim 1933', '30 Haziran 1939'], 'İsviçre\'nin Montrö (Montreux) kentinde yapılan konferans sonucunda 20 Temmuz 1936\'da imzalanan sözleşme ile Boğazlarda tam Türk egemenliği sağlanmıştır.'),
  ('1936 Montrö Boğazlar Sözleşmesi ile Lozan\'dan kalan hangi kurum tamamen kaldırılarak görev ve yetkileri Türkiye Cumhuriyeti\'ne devredilmiştir?', 'Uluslararası Boğazlar Komisyonu', ['Düyun-u Umumiye İdaresi', 'Müttefik Deniz Denetim Kurulu', 'Milletler Cemiyeti Boğazlar Mahkemesi'], 'Montrö Sözleşmesi\'nin 24. maddesiyle Uluslararası Boğazlar Komisyonu\'nun yetkileri Türkiye\'ye devredilmiş ve Türk egemenliğini kısıtlayan yapı sona ermiştir.'),
  ('Birinci Dünya Savaşı\'nda İtilaf Devletleri\'nin Çanakkale Boğazı\'nı denizden zorlayarak İstanbul\'a ulaşmak istedikleri 18 Mart 1915 zaferinde batan düşman zırhlılarının kaderini belirleyen ünlü Türk mayın gemisi hangisidir?', 'Nusret Mayın Gemisi', ['Hamidiye Kruvazörü', 'Yavuz Zırhlısı', 'Muavenet-i Milliye Muhribi'], 'Nusret Mayın Gemisi, döşediği yirmi altı mayınla 18 Mart 1915 Çanakkale Deniz Zaferi\'nin kazanılmasında belirleyici rol oynamıştır.'),
  ('18 Mart 1915 günü Çanakkale\'deki Mecidiye Tabyası\'nda vinç arızalanınca yaklaşık 215-276 kilogramlık top mermisini sırtlayarak namluya süren kahraman asker kimdir?', 'Seyit Onbaşı', ['Yahya Çavuş', 'Nezahat Onbaşı', 'Hasan Tahsin'], 'Balıkesir Havranlı Koca Seyit (Seyit Çabuk), Rumeli Mecidiye Tabyası\'nda ağır top mermisini sırtlayarak ateşlemiş ve İngiliz zırhlısı Ocean\'ın dümen donanımından vurulmasını sağlamıştır.'),
  ('Bir devletin kendi limanları ve karasuları arasında yolcu ve yük taşıma hakkını yalnızca kendi bayrağını taşıyan gemilere tanımasına ne ad verilir?', 'Kabotaj hakkı', ['Kapitülasyon imtiyazı', 'Serbest bölge rejimi', 'Transit geçiş hakkı'], 'Kabotaj, bir ülkenin kendi kıyıları ve limanları arasındaki deniz ticareti ve taşımacılığı tekelini kendi vatandaşlarına ve bayrağına ayırmasıdır.'),
  ('Türkiye\'de Kabotaj Kanunu hangi tarihte yürürlüğe girerek Denizcilik ve Kabotaj Bayramı olarak kutlanmaya başlanmıştır?', '1 Temmuz 1926', ['29 Ekim 1923', '24 Temmuz 1923', '20 Temmuz 1936'], '19 Nisan 1926\'da TBMM\'de kabul edilen 815 sayılı Kabotaj Kanunu, 1 Temmuz 1926 tarihinde yürürlüğe girmiştir.'),
  ('1 Temmuz 1926\'da yürürlüğe giren Kabotaj Kanunu Atatürk ilkelerinden öncelikle hangisinin ekonomik ve hukuki alandaki doğrudan bir uygulamasıdır?', 'Milliyetçilik', ['Cumhuriyetçilik', 'Laiklik', 'Halkçılık'], 'Türk sularında deniz taşımacılığı ve liman hizmetlerini yabancıların tekelinden alıp Türk vatandaşlarına vermesi nedeniyle Kabotaj Kanunu doğrudan Milliyetçilik (ve bağımsızlık) ilkesiyle ilgilidir.'),
  ('Cumhuriyet\'in ilk yıllarında Türkiye\'nin dış dünyaya tanıtılması amacıyla yüzer sergi haline getirilerek 1926 yazında on iki Avrupa ülkesinin limanlarını dolaşan ünlü Türk gemisi hangisidir?', 'Karadeniz Vapuru', ['Gülcemal Vapuru', 'Bandırma Vapuru', 'Ertuğrul Fırkateyni'], '815 sayılı Kabotaj Kanunu\'ndan kısa süre önce Haziran 1926\'da yola çıkan Karadeniz Vapuru, yerli ürünleri ve genç Cumhuriyet\'in modern yüzünü 16 Avrupa limanında tanıtmıştır.'),
  ('Mustafa Kemal Paşa ve silah arkadaşlarını 16 Mayıs 1919\'da İstanbul\'dan alarak 19 Mayıs 1919\'da Samsun\'a ulaştıran tarihi vapur hangisidir?', 'Bandırma Vapuru', ['Alemdar Gemisi', 'İnebolu Vapuru', 'Savarona Yatı'], '9. Ordu Müfettişi Mustafa Kemal Paşa ve beraberindeki heyet, Karadeniz\'in fırtınalı sularını Bandırma Vapuru ile aşarak Samsun\'a çıkmış ve Milli Mücadele\'yi başlatmıştır.'),
  ('Cumhuriyet döneminde devletçilik ilkesi doğrultusunda 1933 ve 1937 yıllarındaki düzenlemelerle Türk deniz ticaretini, liman işletmelerini ve denizcilik kredilerini finanse etmek üzere Atatürk\'ün talimatıyla kurulan kurum hangisidir?', 'Denizbank', ['Sümerbank', 'Etibank', 'Ziraat Bankası'], 'Atatürk\'ün 1937 Meclis açılış konuşmasındaki direktifiyle kurulan Denizbank, devletin deniz taşımacılığı, liman ve tersane işletmelerini tek çatı altında toplayıp geliştirmeyi amaçlamıştır.'),
  ('Mustafa Kemal Atatürk\'ün yaşamının son aylarında devlet işlerini yürüttüğü ve kabine toplantılarını gerçekleştirdiği, 1938 yılında satın alınan tarihi başkanlık yatı hangisidir?', 'Savarona', ['Ertuğrul', 'Mahmudiye', 'Gülcemal'], '1931 yapımı Savarona yatı, 1938 Mart\'ında Türkiye Cumhuriyeti tarafından satın alınmış ve hasta yatağındaki Atatürk son döneminin yaklaşık iki ayını bu yatta geçirmiştir.'),
  ('Osmanlı Padişahı II. Abdülhamid döneminde Japonya\'ya dostluk ziyareti yaptıktan sonra 1890 yılında dönüş yolunda tayfuna yakalanarak Japon sularında batan ve Türk-Japon dostluğunun simgesi olan gemimiz hangisidir?', 'Ertuğrul Fırkateyni', ['Mahmudiye Kalyonu', 'Nusret Mayın Gemisi', 'Aziziye Fırkateyni'], '16 Eylül 1890\'da Japonya\'nın Kuşimoto açıklarında kayalıklara çarparak batan Ertuğrul Fırkateyni\'nden sağ kurtulan 69 denizcimize Japon köylülerinin gösterdiği yardım tarihi dostluğu başlatmıştır.'),
  ('Çanakkale Boğazı\'nda 18 Mart 1915 Deniz Zaferi her yıl Türkiye\'de hangi adla anılmakta ve kutlanmaktadır?', '18 Mart Şehitleri Anma Günü ve Çanakkale Deniz Zaferi', ['1 Temmuz Denizcilik ve Kabotaj Bayramı', '27 Eylül Preveze Deniz Zaferi ve Deniz Kuvvetleri Günü', '30 Ağustos Başkomutanlık ve Zafer Bayramı'], '18 Mart günü, vatan savunmasında can veren şehitlerimizi anmak ve Çanakkale Deniz Zaferi\'ni yaşatmak amacıyla resmi olarak "Şehitleri Anma Günü ve Çanakkale Deniz Zaferi" olarak kutlanır.'),
  ('2016 yılında genişletme çalışmaları tamamlanarak "Yeni Panamax" (Neopanamax) sınıfı dev konteyner gemilerinin geçişine açılan Panama Kanalı\'nda genişletme ihtiyacı neden doğmuştur?', 'Küresel deniz ticaretinde gemi boyutlarının ve yük kapasitelerinin eski havuzlara sığmayacak kadar büyümesi', ['Atlas Okyanusu\'ndaki su seviyesinin Büyük Okyanus\'a göre on metre yükselmesi', 'Kanal içindeki tuzlu suyun gemilerin çelik gövdelerini hızla aşındırması', 'Orta Amerika\'daki demiryolu taşımacılığının tamamen yürürlükten kalkması'], '1914\'te yapılan havuz boyutları (Panamax standardı) çağdaş dev konteyner ve LNG gemilerine dar geldiği için Panama üçüncü bir dev kapak ve havuz şeridi inşa ederek 2016\'da hizmete açmıştır.'),
  ('Cumhuriyet döneminde kurulan Türkiye Denizcilik İşletmeleri ve öncülü kurumların İstanbul\'da şehir içi deniz ulaşımında simgeleşmiş, yolcu taşıyan klasik boğaz vapurlarına halk ve kültür tarihinde verilen genel ad nedir?', 'Şehir Hatları vapuru', ['Kalyon sınıfı fırkateyn', 'Açık deniz şilebi', 'Koster tipi tanker'], 'İstanbul\'un iki yakasını birbirine bağlayan klasik yolcu vapurları, Cumhuriyet kent kültürünün ayrılmaz bir parçası olan Şehir Hatları vapurları olarak tanınmıştır.'),
  ('Cumhuriyet döneminde her yıl 1 Temmuz gününde sahil kentlerimizde yağlı direk yarışları, yüzme müsabakaları ve şehit denizciler için denize çelenk bırakma törenleriyle kutlanan ulusal gün hangisidir?', 'Denizcilik ve Kabotaj Bayramı', ['Donanma ve Tersaneler Günü', 'Boğazlar ve Montrö Zaferi Günü', 'Akdeniz Ticaret Filosu Bayramı'], '1 Temmuz 1926\'da Kabotaj Kanunu\'nun yürürlüğe girmesinin yıl dönümü, 1935\'ten itibaren Denizcilik (ve daha sonra Denizcilik ve Kabotaj) Bayramı olarak deniz şenlikleri ve törenlerle kutlanmaktadır.'),
  ('Süveyş ve Panama kanallarının dünya deniz ticaretine sağladığı en temel ortak ekonomik katkı nedir?', 'Kıtalar arası deniz yolculuğu mesafesini, süresini ve yakıt maliyetini büyük ölçüde azaltmaları', ['Okyanuslardaki gelgit ve fırtına olaylarını küresel ölçekte tamamen sona erdirmeleri', 'Kuru yük gemilerinin kara demiryollarına hiç ihtiyaç duymadan iç şehirlere girmesini sağlamaları', 'Dünya üzerindeki bütün boğazların gemi trafiğine kapatılmasını zorunlu kılmaları'], 'Her iki kanal da kıtaların etrafını (Afrika\'da Ümit Burnu, Güney Amerika\'da Horn Burnu) dolaşma zorunluluğunu ortadan kaldırarak binlerce deniz mili tasarruf sağlamıştır.'),
];
